package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;

class VisualFieldConsumptionTest {
    private Document doc(String body){return new Document("bid","project","BID","fixture.pdf",1,"sha","",cn.bidcheck.compat.Java8Api.listOf(new Page(1,body,"PAGE","PDF","")),cn.bidcheck.compat.Java8Api.listOf());}
    private Map<String,Object> observation(){return linked("id","v","documentId","bid","location",1,"locationType","PAGE","imageHash","img","type","FIELD","label","姓名","value","张甲","readability","CLEAR","sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 20, 20),"modelLimitations",cn.bidcheck.compat.Java8Api.listOf("仅基于单页图像识别，未验证证书真伪或有效性"),"source",cn.bidcheck.compat.Java8Api.mapOf("documentHash", "sha", "renderedSha256", "img", "documentVersion", 1, "page", 1));}
    private Rule role(){return new Rule("r","项目负责人","PERSON_ROLE","项目负责人","姓名","","","",cn.bidcheck.compat.Java8Api.mapOf(),"项目负责人","",cn.bidcheck.compat.Java8Api.listOf());}
    @Test void clearObservationBecomesLiteralFactWithoutInventingSubject(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("本项目人员配置")));c.addVisualObservations(cn.bidcheck.compat.Java8Api.listOf(observation()));List<Source> visual=cn.bidcheck.compat.Java8Api.toList(c.all.stream().filter(s->s.id().startsWith("V")));assertEquals(1,visual.size());Fact f=c.nativeFacts(cn.bidcheck.compat.Java8Api.listOf(role()),visual).get(0);assertEquals("FIELD",f.kind());assertEquals("UNRESOLVED",f.scope());assertEquals("",f.subject());assertNull(new ProofVerifier().issue(f,c.byId));assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(f),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(role()).status());}
    @Test void modelCannotTurnVisualLabelIntoPersonRole(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("本项目人员配置")));java.util.Map<java.lang.String, java.lang.Object> o=observation();o.put("label","项目负责人");c.addVisualObservations(cn.bidcheck.compat.Java8Api.listOf(o));Source v=c.all.stream().filter(s->s.id().startsWith("V")).findFirst().orElseThrow(java.util.NoSuchElementException::new);Fact f=new Fact("x","PERSON_ROLE","项目负责人","姓名","张甲","张甲","","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(v.id()),cn.bidcheck.compat.Java8Api.mapOf());assertEquals("VISUAL_FIELD_RELATION_REQUIRES_ORIGINAL_SOURCE",new ProofVerifier().issue(f,c.byId));}
    @Test void wrongVersionAndWrongCoordinatesRemainRejected(){for(Object replacement:cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("documentHash", "sha", "renderedSha256", "img", "documentVersion", 2), cn.bidcheck.compat.Java8Api.mapOf("documentHash", "wrong", "renderedSha256", "img"))){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("正文")));java.util.Map<java.lang.String, java.lang.Object> o=observation();o.put("source",replacement);c.addVisualObservations(cn.bidcheck.compat.Java8Api.listOf(o));assertTrue(c.all.stream().noneMatch(s->s.id().startsWith("V")));}}
    @Test void repeatedObservationDoesNotDuplicateSource(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("正文")));c.addVisualObservations(cn.bidcheck.compat.Java8Api.listOf(observation(), observation()));assertEquals(1,c.all.stream().filter(s->s.id().startsWith("V")).count());}
    @Test void ordinarySealPassesWithAuthenticityDisclaimerButNotWrongDocument(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("本项目授权书\n甲公司授权书盖章位置")));Rule r=new Rule("r","甲公司授权书盖章","VISUAL","甲公司","seal","","","",cn.bidcheck.compat.Java8Api.mapOf("documentType", "授权书"),"甲公司授权书盖章","",cn.bidcheck.compat.Java8Api.listOf());java.util.Map<java.lang.String, java.lang.Object> o=observation();o.put("obligationId","r");o.put("type","SEAL");o.put("label","印章");o.put("value","甲公司");o.put("observedValue","甲公司");o.put("modelLimitations",cn.bidcheck.compat.Java8Api.listOf("无法确认印章真伪及法律效力"));assertEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(o))).evaluate(r).status());o.put("obligationId","different");assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(o))).evaluate(r).status());}
}
